function exist(board, word) {
  const m = board.length, n = board[0].length;
  const visited = Array.from({ length: m }, () => new Array(n).fill(false));
  function dfs(r, c, k) {
    if (k === word.length) return true;
    if (r < 0 || r >= m || c < 0 || c >= n || visited[r][c] || board[r][c] !== word[k]) {
      return false;
    }
    visited[r][c] = true;
    const found = dfs(r + 1, c, k + 1) || dfs(r - 1, c, k + 1) || dfs(r, c + 1, k + 1) || dfs(r, c - 1, k + 1);
    visited[r][c] = false;
    return found;
  }
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (dfs(i, j, 0)) return true;
    }
  }
  return false;
}

function exist(board, word) {
  const m = board.length, n = board[0].length;
  if (word.length > m * n) return false;
  const boardCount = {};
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      boardCount[board[i][j]] = (boardCount[board[i][j]] || 0) + 1;
    }
  }
  const wordCount = {};
  for (let i = 0; i < word.length; i++) {
    wordCount[word[i]] = (wordCount[word[i]] || 0) + 1;
    if ((boardCount[word[i]] || 0) < wordCount[word[i]]) return false;
  }
  let targetWord = word;
  if ((boardCount[word[0]] || 0) > (boardCount[word[word.length - 1]] || 0)) {
    targetWord = word.split("").reverse().join("");
  }
  function dfs(r, c, k) {
    if (k === targetWord.length) return true;
    if (r < 0 || r >= m || c < 0 || c >= n || board[r][c] !== targetWord[k]) return false;
    const saved = board[r][c];
    board[r][c] = "#";
    const found = dfs(r + 1, c, k + 1) || dfs(r - 1, c, k + 1) || dfs(r, c + 1, k + 1) || dfs(r, c - 1, k + 1);
    board[r][c] = saved;
    return found;
  }
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (board[i][j] === targetWord[0] && dfs(i, j, 0)) return true;
    }
  }
  return false;
}

def exist(board: list[list[str]], word: str) -> bool:
    m, n = len(board), len(board[0])
    visited = [[False] * n for _ in range(m)]

    def dfs(r: int, c: int, k: int) -> bool:
        if k == len(word):
            return True
        if r < 0 or r >= m or c < 0 or c >= n or visited[r][c] or board[r][c] != word[k]:
            return False
        visited[r][c] = True
        found = (
            dfs(r + 1, c, k + 1)
            or dfs(r - 1, c, k + 1)
            or dfs(r, c + 1, k + 1)
            or dfs(r, c - 1, k + 1)
        )
        visited[r][c] = False
        return found

    for i in range(m):
        for j in range(n):
            if dfs(i, j, 0):
                return True
    return False

def exist(board: list[list[str]], word: str) -> bool:
    m, n = len(board), len(board[0])
    if len(word) > m * n:
        return False
    from collections import Counter
    board_cnt = Counter(ch for row in board for ch in row)
    word_cnt = Counter(word)
    for ch, count in word_cnt.items():
        if board_cnt[ch] < count:
            return False
    target = word
    if board_cnt[word[0]] > board_cnt[word[-1]]:
        target = word[::-1]

    def dfs(r: int, c: int, k: int) -> bool:
        if k == len(target):
            return True
        if r < 0 or r >= m or c < 0 or c >= n or board[r][c] != target[k]:
            return False
        saved = board[r][c]
        board[r][c] = "#"
        found = (
            dfs(r + 1, c, k + 1)
            or dfs(r - 1, c, k + 1)
            or dfs(r, c + 1, k + 1)
            or dfs(r, c - 1, k + 1)
        )
        board[r][c] = saved
        return found

    for i in range(m):
        for j in range(n):
            if board[i][j] == target[0] and dfs(i, j, 0):
                return True
    return False
